import React, { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

// Register GSAP ScrollTrigger plugin
gsap.registerPlugin(ScrollTrigger);

const ProductAndServices = () => {
  const card1Ref = useRef(null);
  const card2Ref = useRef(null);
  const card3Ref = useRef(null);

  useEffect(() => {
    const cards = [card1Ref.current, card2Ref.current, card3Ref.current];

    cards.forEach((card, index) => {
      gsap.to(card, {
        scrollTrigger: {
          trigger: card,
          start: "top center", // When card enters the center of viewport
          end: () => "+=" + card.offsetHeight, // End point based on card height
          pin: true, // Pin the card
          scrub: true, // Smooth scroll effect
          markers: false, // Remove this in production
        },
        opacity: 1,
        y: 0,
      });
    });
  }, []);

  return (
    <section className="py-16 bg-primary-light border-t border-b border-blue-300" id="product">
      <div className="container mx-auto">
        <h2 className="text-3xl font-bold text-center mb-8 text-white">
          PRODUCTS & SERVICES
        </h2>

        <div className="relative space-y-16">

          {/* First Card */}
          <div ref={card1Ref} className="card opacity-0 relative">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700 min-h-[350px]">
              <img className="object-cover w-full rounded-t-lg min-h-[350px] md:h-auto md:w-96 md:rounded-none md:rounded-s-lg" src="./images/Cricket.jpg" alt="Cricket Image"/>
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">
                  MATCH GRAPHICS
                </h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">
                  Our Match Graphics service is designed to bring real-time, data-driven visuals...
                </p>
              </div>
            </div>
          </div>

          {/* Second Card */}
          <div ref={card2Ref} className="card opacity-0 relative">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700 min-h-[350px]">
              <img className="object-cover w-full rounded-t-lg min-h-[350px] md:h-auto md:w-96 md:rounded-none md:rounded-s-lg" src="./images/Cricket2.jpg" alt="Cricket Image"/>
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">
                  LIVE STATS
                </h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">
                  Our live stats service provides comprehensive, real-time statistics...
                </p>
              </div>
            </div>
          </div>

          {/* Third Card */}
          <div ref={card3Ref} className="card opacity-0 relative">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700 min-h-[350px]">
              <img className="object-cover w-full rounded-t-lg min-h-[350px] md:h-auto md:w-96 md:rounded-none md:rounded-s-lg" src="./images/Cricket3.jpg" alt="Cricket Image"/>
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">
                  TEAM LINEUPS
                </h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">
                  Display complete team lineups dynamically in your broadcasts for better engagement...
                </p>
              </div>
            </div>
          </div>

        </div>
      </div>
    </section>
  );
};

export default ProductAndServices;
